const toRad = (deg) => deg * Math.PI / 180;

// Location 1: User's current device location (San Francisco, CA)
const lat1 = 37.7749, lon1 = -122.4194;

// Location 2: Boston, MA 02118 (approximate center of zip code)
const lat2 = 42.3388, lon2 = -71.0726;

// Haversine formula
const R = 3958.8; // Earth's radius in miles
const dLat = toRad(lat2 - lat1);
const dLon = toRad(lon2 - lon1);
const a = Math.sin(dLat/2)**2 + Math.cos(toRad(lat1)) * Math.cos(toRad(lat2)) * Math.sin(dLon/2)**2;
const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
const distMiles = R * c;
const distKm = distMiles * 1.60934;

console.log('=== Distance Calculation ===');
console.log('');
console.log('From:  (37.7749, -122.4194) — San Francisco, CA');
console.log('To:    4829 Elm Ridge Way, Suite 7, Boston, MA 02118');
console.log('       (approx. 42.3388, -71.0726)');
console.log('');
console.log('Great-circle distance:');
console.log('  ' + distMiles.toFixed(1).replace(/\B(?=(\d{3})+(?!\d))/g, ',') + ' miles');
console.log('  ' + distKm.toFixed(1).replace(/\B(?=(\d{3})+(?!\d))/g, ',') + ' kilometers');
console.log('');
console.log('Note: Actual driving distance will typically be longer.');
"
